-- knowledge_entry: 6 rows

-- business_notification: 7 rows

-- operation_log: 20 rows

-- Any failed assertion aborts the client and rolls back this transaction.
COMMIT;
SELECT COUNT(*) AS passed_seed_assertions FROM `_eit_seed_check`;
DROP TEMPORARY TABLE `_eit_seed_check`;
