INSERT INTO `_eit_seed_check` VALUES ('count_org_department', ((SELECT COUNT(*) FROM `org_department` WHERE `department_id` IN (910001,910002,910003,910004))=4));
INSERT INTO `_eit_seed_check` VALUES ('count_employee', ((SELECT COUNT(*) FROM `employee` WHERE `employee_id` IN (910001,910002,910003,910004,910005,910006,910007,910008,910009,910010))=10));
INSERT INTO `_eit_seed_check` VALUES ('count_customer_profile', ((SELECT COUNT(*) FROM `customer_profile` WHERE `customer_id` IN (910001,910002,910003,910004,910005,910006,910007))=7));
INSERT INTO `_eit_seed_check` VALUES ('count_customer_followup', ((SELECT COUNT(*) FROM `customer_followup` WHERE `followup_id` IN (910001,910002,910003,910004,910005,910006,910007))=7));
INSERT INTO `_eit_seed_check` VALUES ('count_employee_daily_report', ((SELECT COUNT(*) FROM `employee_daily_report` WHERE `daily_report_id` IN (910001,910002,910003,910004,910005,910006))=6));
INSERT INTO `_eit_seed_check` VALUES ('count_student_profile', ((SELECT COUNT(*) FROM `student_profile` WHERE `student_id` IN (910001,910002,910003,910004,910005))=5));
INSERT INTO `_eit_seed_check` VALUES ('count_student_staff_binding', ((SELECT COUNT(*) FROM `student_staff_binding` WHERE `binding_id` IN (910001,910002,910003,910004,910005,910006,910007,910008,910009,910010,910011,910012,910013))=13));
INSERT INTO `_eit_seed_check` VALUES ('count_student_score', ((SELECT COUNT(*) FROM `student_score` WHERE `score_id` IN (910001,910002,910003,910004,910005,910006))=6));
INSERT INTO `_eit_seed_check` VALUES ('count_student_leave_request', ((SELECT COUNT(*) FROM `student_leave_request` WHERE `leave_request_id` IN (910001,910002,910003,910004,910005))=5));
INSERT INTO `_eit_seed_check` VALUES ('count_service_ticket', ((SELECT COUNT(*) FROM `service_ticket` WHERE `ticket_id` IN (910001,910002,910003,910004,910005,910006))=6));
INSERT INTO `_eit_seed_check` VALUES ('count_service_ticket_record', ((SELECT COUNT(*) FROM `service_ticket_record` WHERE `ticket_record_id` IN (910001,910002,910003,910004,910005,910006,910007,910008,910009,910010,910011,910012,910013,910014,910015,910016,910017))=17));
INSERT INTO `_eit_seed_check` VALUES ('count_knowledge_entry', ((SELECT COUNT(*) FROM `knowledge_entry` WHERE `knowledge_id` IN (910001,910002,910003,910004,910005,910006))=6));
INSERT INTO `_eit_seed_check` VALUES ('count_business_notification', ((SELECT COUNT(*) FROM `business_notification` WHERE `notification_id` IN (910001,910002,910003,910004,910005,910006,910007))=7));
INSERT INTO `_eit_seed_check` VALUES ('count_operation_log', ((SELECT COUNT(*) FROM `operation_log` WHERE `operation_log_id` IN (910001,910002,910003,910004,910005,910006,910007,910008,910009,910010,910011,910012,910013,910014,910015,910016,910017,910018,910019,910020))=20));
INSERT INTO `_eit_seed_check` VALUES ('one_primary_teacher', (NOT EXISTS (SELECT student_id FROM student_staff_binding WHERE student_id BETWEEN 910001 AND 910005 AND relation_type='class_teacher' AND status='active' AND is_primary=1 AND valid_from<=@eit_now AND (valid_to IS NULL OR valid_to>@eit_now) GROUP BY student_id HAVING COUNT(*)>1)));
INSERT INTO `_eit_seed_check` VALUES ('score_permissions', (NOT EXISTS (SELECT 1 FROM student_score s WHERE s.score_id BETWEEN 910001 AND 910006 AND NOT EXISTS (SELECT 1 FROM student_staff_binding b WHERE b.student_id=s.student_id AND b.employee_id=s.employee_id AND b.relation_type='score_editor' AND b.course_scope_code=s.course_code AND b.status='active' AND b.valid_from<=@eit_now AND (b.valid_to IS NULL OR b.valid_to>@eit_now)))));
INSERT INTO `_eit_seed_check` VALUES ('leave_approvers', (NOT EXISTS (SELECT 1 FROM student_leave_request l WHERE l.leave_request_id BETWEEN 910001 AND 910005 AND l.approver_employee_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM student_staff_binding b WHERE b.student_id=l.student_id AND b.employee_id=l.approver_employee_id AND b.relation_type='class_teacher' AND b.status='active' AND b.valid_from<=@eit_now AND (b.valid_to IS NULL OR b.valid_to>@eit_now)))));
INSERT INTO `_eit_seed_check` VALUES ('ticket_owners', (NOT EXISTS (SELECT 1 FROM service_ticket t WHERE t.ticket_id BETWEEN 910001 AND 910006 AND t.employee_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM student_staff_binding b WHERE b.student_id=t.student_id AND b.employee_id=t.employee_id AND b.relation_type='service_advisor' AND b.status='active'))));
INSERT INTO `_eit_seed_check` VALUES ('student_ticket_records', (NOT EXISTS (SELECT 1 FROM service_ticket_record r JOIN service_ticket t ON t.ticket_id=r.ticket_id WHERE r.ticket_record_id BETWEEN 910001 AND 910100 AND r.student_id IS NOT NULL AND r.student_id<>t.student_id)));
INSERT INTO `_eit_seed_check` VALUES ('record_cycles', (NOT EXISTS (SELECT 1 FROM service_ticket_record r JOIN service_ticket t ON t.ticket_id=r.ticket_id WHERE r.ticket_record_id BETWEEN 910001 AND 910100 AND r.cycle_no>t.reopen_count+1)));
INSERT INTO `_eit_seed_check` VALUES ('notification_targets', (NOT EXISTS (SELECT 1 FROM business_notification n WHERE n.notification_id BETWEEN 910001 AND 910007 AND ((n.entity_type='leave' AND NOT EXISTS (SELECT 1 FROM student_leave_request l WHERE l.leave_request_id=n.entity_id)) OR (n.entity_type='ticket' AND NOT EXISTS (SELECT 1 FROM service_ticket t WHERE t.ticket_id=n.entity_id)) OR (n.entity_type='customer_followup' AND NOT EXISTS (SELECT 1 FROM customer_followup f WHERE f.followup_id=n.entity_id))))));
INSERT INTO `_eit_seed_check` VALUES ('notification_students', (NOT EXISTS (SELECT 1 FROM business_notification n WHERE n.notification_id BETWEEN 910001 AND 910007 AND n.student_id IS NOT NULL AND ((n.entity_type='leave' AND NOT EXISTS (SELECT 1 FROM student_leave_request l WHERE l.leave_request_id=n.entity_id AND l.student_id=n.student_id)) OR (n.entity_type='ticket' AND NOT EXISTS (SELECT 1 FROM service_ticket t WHERE t.ticket_id=n.entity_id AND t.student_id=n.student_id))))));
INSERT INTO `_eit_seed_check` VALUES ('six_roles', ((SELECT COUNT(DISTINCT j.role_code) FROM employee e,JSON_TABLE(e.role_codes,'$[*]' COLUMNS(role_code VARCHAR(32) PATH '$')) j WHERE e.employee_id BETWEEN 910001 AND 910010)=6));
INSERT INTO `_eit_seed_check` VALUES ('terminal_ticket_times', (NOT EXISTS (SELECT 1 FROM service_ticket WHERE ticket_id BETWEEN 910001 AND 910006 AND ((status='closed' AND (closed_at IS NULL OR resolved_at IS NULL)) OR (status='awaiting_student' AND (resolved_at IS NULL OR closed_at IS NOT NULL)) OR (status='reopened' AND (reopen_count<1 OR closed_at IS NOT NULL))))));
